use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_u64().unwrap();

    let mut indices = Vec::new();
    let mut current_index = 0;

    while current_index < jobs.len() {
        let job = jobs[current_index];
        let remaining_quantum = quantum;

        while remaining_quantum > 0 {
            if current_index >= jobs.len() {
                break;
            }

            let next_job = jobs[current_index];
            let next_remaining_quantum = quantum;

            if next_job > remaining_quantum {
                next_remaining_quantum = remaining_quantum - next_job;
            } else {
                indices.push(current_index);
                remaining_quantum -= next_job;
                current_index += 1;
            }
        }

        if remaining_quantum > 0 {
            indices.push(current_index);
        }
    }

    serde_json::Value::Array(indices)
}
